            className="flex-1 bg-transparent text-zinc-100 placeholder-zinc-600 outline-none text-xs"
          />
          <button type="submit" className="text-zinc-500 hover:text-zinc-300">
            <Play size={10} weight="fill" />
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  alpha: number;
  color: string;
}

export const FluidParticleCursor: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particlesRef = useRef<Particle[]>([]);
  const lastPosRef = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    const colors = ['#6366f1', '#38bdf8', '#a855f7', '#34d399', '#f43f5e'];

    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.alpha *= 0.94;
        p.size *= 0.97;

        if (p.alpha < 0.02 || p.size < 0.5) {
          particlesRef.current.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      animId = requestAnimationFrame(render);
    };

    render();

    return () => cancelAnimationFrame(animId);
  }, []);

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const colors = ['#6366f1', '#38bdf8', '#a855f7', '#34d399', '#f43f5e'];

    for (let i = 0; i < 3; i++) {
      particlesRef.current.push({
        x,
        y,
        vx: (Math.random() - 0.5) * 2.5,
        vy: (Math.random() - 0.5) * 2.5,
        size: Math.random() * 3.5 + 2,
        alpha: 1,
        color: colors[Math.floor(Math.random() * colors.length)],
      });
    }
  };

  return (
    <div className="relative w-full h-64 rounded-2xl overflow-hidden bg-zinc-950 border border-white/10 flex items-center justify-center">
      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
        <span className="text-xs font-mono uppercase tracking-widest text-zinc-500">
          Move cursor to draw luminous stardust
        </span>
        <span className="text-[11px] font-mono text-zinc-600 mt-1">Velocity Particle Dispersion</span>
      </div>
      <canvas
        ref={canvasRef}
        width={500}
        height={256}
        onMouseMove={handleMouseMove}
        className="w-full h-full cursor-crosshair"
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, useSpring, useMotionValue } from 'framer-motion';

export const MagneticCursorFollower: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = useState(false);
  const [activeTarget, setActiveTarget] = useState<string | null>(null);

  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const springConfig = { damping: 25, stiffness: 350 };
  const cursorX = useSpring(mouseX, springConfig);
  const cursorY = useSpring(mouseY, springConfig);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    mouseX.set(e.clientX - rect.left);
    mouseY.set(e.clientY - rect.top);
  };

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => {
        setIsHovered(false);
        setActiveTarget(null);
      }}
      className="relative w-full h-64 rounded-2xl overflow-hidden bg-zinc-950/80 border border-white/10 flex flex-col items-center justify-center gap-4 cursor-none p-6 select-none"
    >
      <span className="text-xs font-mono uppercase tracking-widest text-zinc-500">
        Move pointer over interactive elements
      </span>

      <div className="flex items-center gap-4 z-10">
        {['Deploy', 'Analyze', 'Terminal'].map((label) => (
          <button
            key={label}
            onMouseEnter={() => setActiveTarget(label)}
            onMouseLeave={() => setActiveTarget(null)}
            className="px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-xs font-mono text-zinc-300 hover:text-white hover:border-indigo-500/50 hover:bg-indigo-500/10 transition-colors"
          >
            {label}
          </button>
        ))}
      </div>

      {/* Spring Follower Cursor */}
      {isHovered && (
        <motion.div
          style={{ x: cursorX, y: cursorY }}
          className="pointer-events-none absolute top-0 left-0 -translate-x-1/2 -translate-y-1/2 z-30"
        >
          <motion.div
            animate={{
              scale: activeTarget ? 1.8 : 1,
              borderColor: activeTarget ? 'rgba(99, 102, 241, 0.9)' : 'rgba(255, 255, 255, 0.5)',
              backgroundColor: activeTarget ? 'rgba(99, 102, 241, 0.15)' : 'transparent',
            }}
            transition={{ type: 'spring', damping: 20, stiffness: 300 }}
            className="w-8 h-8 rounded-full border-2 backdrop-blur-xs flex items-center justify-center"
          >
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-400" />
          </motion.div>
        </motion.div>
      )}
    </div>
  );
};

